from dataclasses import dataclass

# Constants for categories and their valid values
PRICES_MAP = {
    "$300": 300,
    "$350": 350,
    "$400": 400,
    "$475": 475,
}
ALL_PRICES_INT = set(PRICES_MAP.values())
ALL_BRANDS = {"Bulova", "Citizen", "Hamilton", "Seiko"}
ALL_FACE_COLORS = {"blue", "green", "red", "silver"}
TOTAL_CLUES = 5

@dataclass
class Watch:
    price: int
    brand: str
    face_color: str

def clue0(Watches_by_Brand, Watches_by_FaceColor):
    # Clue 1: The Tissot watch was either the timepiece with a silver face or the one with a blue dial.
    # "Tissot" is not listed in the puzzle's allowed brands.
    # Therefore, a "Tissot watch" cannot exist in a valid solution for this puzzle.
    # This clue cannot be satisfied.
    tissot_watch = Watches_by_Brand.get("Tissot")
    if tissot_watch is None:
        return False # Tissot watch does not exist in the puzzle's defined brands.

    # This part would only be reached if "Tissot" was an allowed brand.
    return tissot_watch.face_color == "silver" or tissot_watch.face_color == "blue"

def clue1(Watches_by_Brand, Watches_by_FaceColor):
    # Clue 2: The watch with a blue dial sold for 75 dollars less than the Bulova model.
    blue_watch = Watches_by_FaceColor.get("blue")
    bulova_watch = Watches_by_Brand.get("Bulova")
    if blue_watch is None or bulova_watch is None:
        return False # Should not happen with valid input, but defensive.
    return blue_watch.price == bulova_watch.price - 75

def clue2(Watches_by_Price):
    # Clue 3: Of the $400 watch and the $350 piece, one is a Hamilton model and the other has a green face.
    watch_400 = Watches_by_Price.get(400)
    watch_350 = Watches_by_Price.get(350)
    if watch_400 is None or watch_350 is None:
        return False # Should not happen with valid input, but defensive.

    cond1 = (watch_400.brand == "Hamilton" and watch_350.face_color == "green")
    cond2 = (watch_350.brand == "Hamilton" and watch_400.face_color == "green")
    return cond1 or cond2

def clue3(Watches_by_Brand):
    # Clue 4: The Seiko model sold for somewhat more than the Citizen model.
    seiko_watch = Watches_by_Brand.get("Seiko")
    citizen_watch = Watches_by_Brand.get("Citizen")
    if seiko_watch is None or citizen_watch is None:
        return False # Should not happen with valid input, but defensive.
    return seiko_watch.price > citizen_watch.price

def clue4(Watches_by_FaceColor):
    # Clue 5: The watch with a silver face sold for 125 dollars more than the timepiece with a green face.
    silver_watch = Watches_by_FaceColor.get("silver")
    green_watch = Watches_by_FaceColor.get("green")
    if silver_watch is None or green_watch is None:
        return False # Should not happen with valid input, but defensive.
    return silver_watch.price == green_watch.price + 125

def verify(grid):
    # --- Input Validation and Parsing ---
    if not isinstance(grid, list) or len(grid) != len(ALL_PRICES_INT):
        return (0.0, list(range(TOTAL_CLUES)))

    watches_data = []
    seen_prices = set()
    seen_brands = set()
    seen_face_colors = set()

    for row_idx, row in enumerate(grid):
        if not isinstance(row, list) or len(row) != 3:
            return (0.0, list(range(TOTAL_CLUES)))

        price_str, brand, face_color = row

        # Validate and parse price
        if price_str not in PRICES_MAP:
            return (0.0, list(range(TOTAL_CLUES)))
        price_int = PRICES_MAP[price_str]
        if price_int in seen_prices:
            return (0.0, list(range(TOTAL_CLUES))) # Duplicate price in grid
        seen_prices.add(price_int)

        # Validate brand
        if brand not in ALL_BRANDS:
            return (0.0, list(range(TOTAL_CLUES)))
        if brand in seen_brands:
            return (0.0, list(range(TOTAL_CLUES))) # Duplicate brand in grid
        seen_brands.add(brand)

        # Validate face_color
        if face_color not in ALL_FACE_COLORS:
            return (0.0, list(range(TOTAL_CLUES)))
        if face_color in seen_face_colors:
            return (0.0, list(range(TOTAL_CLUES))) # Duplicate face_color in grid
        seen_face_colors.add(face_color)

        watches_data.append(Watch(price=price_int, brand=brand, face_color=face_color))

    # Ensure all categories are fully represented and unique
    if not (seen_prices == ALL_PRICES_INT and
            seen_brands == ALL_BRANDS and
            seen_face_colors == ALL_FACE_COLORS):
        return (0.0, list(range(TOTAL_CLUES)))

    # Create lookup maps for easy access in clue functions
    Watches_by_Price = {w.price: w for w in watches_data}
    Watches_by_Brand = {w.brand: w for w in watches_data}
    Watches_by_FaceColor = {w.face_color: w for w in watches_data}

    # --- Clue Evaluation ---
    clue_results = [
        clue0(Watches_by_Brand, Watches_by_FaceColor),
        clue1(Watches_by_Brand, Watches_by_FaceColor),
        clue2(Watches_by_Price),
        clue3(Watches_by_Brand),
        clue4(Watches_by_FaceColor),
    ]

    failed_clues = [idx for idx, ok in enumerate(clue_results) if not ok]

    # Calculate reward
    satisfied_clues = sum(clue_results)
    reward = float(satisfied_clues) / TOTAL_CLUES

    return reward, failed_clues

