from dataclasses import dataclass

BIRTHDAYS = {
    "April 3rd": 3,
    "April 7th": 7,
    "April 11th": 11,
    "April 15th": 15,
    "April 19th": 19,
}

@dataclass
class Grandchild:
    name: str
    birthday: int = None
    age: int = None

@dataclass
class Age:
    value: int
    grandchild: str = None
    birthday: int = None

@dataclass
class Birthday:
    day: int
    grandchild: str = None
    age: int = None

def clue0(Grandchildren, Ages, Birthdays_map):
    # Guy isn't 9 years old.
    return Grandchildren["Guy"].age != 9

def clue1(Grandchildren, Ages, Birthdays_map):
    # Johanna was born on April 11th.
    return Grandchildren["Johanna"].birthday == BIRTHDAYS["April 11th"]

def clue2(Grandchildren, Ages, Birthdays_map):
    # Kerry is 8 years old.
    return Grandchildren["Kerry"].age == 8

def clue3(Grandchildren, Ages, Birthdays_map):
    # The 14-year-old has a birthday 4 days after Nathaniel.
    return Ages[14].birthday == Grandchildren["Nathaniel"].birthday + 4

def clue4(Grandchildren, Ages, Birthdays_map):
    # Nathaniel has a birthday 4 days before Bryan.
    return Grandchildren["Nathaniel"].birthday == Grandchildren["Bryan"].birthday - 4

def clue5(Grandchildren, Ages, Birthdays_map):
    # The five children are Kerry, the 5-year-old, the grandchild with the April 15th birthday, the grandchild with the April 11th birthday and the child with the April 7th birthday.

    # Find the grandchild names for the given properties
    grandchild_5_year_old = Ages[5].grandchild
    grandchild_april_15th = Birthdays_map[BIRTHDAYS["April 15th"]].grandchild
    grandchild_april_11th = Birthdays_map[BIRTHDAYS["April 11th"]].grandchild
    grandchild_april_7th = Birthdays_map[BIRTHDAYS["April 7th"]].grandchild

    values = {
        "Kerry",
        grandchild_5_year_old,
        grandchild_april_15th,
        grandchild_april_11th,
        grandchild_april_7th,
    }
    return len(values) == 5

def verify(grid):
    grandchild_names = {"Bryan", "Guy", "Johanna", "Kerry", "Nathaniel"}
    ages_values = {5, 8, 9, 14, 18}
    birthday_days = set(BIRTHDAYS.values())

    if not (isinstance(grid, list) and len(grid) == 5):
        return 0.0, list(range(6))

    parsed_data = []
    for row in grid:
        if not (isinstance(row, list) and len(row) == 3):
            return 0.0, list(range(6))

        birthday_str, grandchild_name, age_str = row

        if birthday_str not in BIRTHDAYS:
            return 0.0, list(range(6))
        birthday_day = BIRTHDAYS[birthday_str]

        if grandchild_name not in grandchild_names:
            return 0.0, list(range(6))

        try:
            age_val = int(age_str)
        except ValueError:
            return 0.0, list(range(6))
        if age_val not in ages_values:
            return 0.0, list(range(6))

        parsed_data.append((birthday_day, grandchild_name, age_val))

    # Check for uniqueness within categories
    if len({d[0] for d in parsed_data}) != 5 or \
       len({d[1] for d in parsed_data}) != 5 or \
       len({d[2] for d in parsed_data}) != 5:
        return 0.0, list(range(6))

    Grandchildren = {}
    Ages = {}
    Birthdays_map = {}

    for birthday_day, grandchild_name, age_val in parsed_data:
        Grandchildren[grandchild_name] = Grandchild(name=grandchild_name, birthday=birthday_day, age=age_val)
        Ages[age_val] = Age(value=age_val, grandchild=grandchild_name, birthday=birthday_day)
        Birthdays_map[birthday_day] = Birthday(day=birthday_day, grandchild=grandchild_name, age=age_val)

    # Defensive check for missing keys if parsing was incomplete or incorrect
    for name in grandchild_names:
        if name not in Grandchildren:
            return 0.0, list(range(6))
    for age_val in ages_values:
        if age_val not in Ages:
            return 0.0, list(range(6))
    for day_val in birthday_days:
        if day_val not in Birthdays_map:
            return 0.0, list(range(6))

    clue_results = [
        clue0(Grandchildren, Ages, Birthdays_map),
        clue1(Grandchildren, Ages, Birthdays_map),
        clue2(Grandchildren, Ages, Birthdays_map),
        clue3(Grandchildren, Ages, Birthdays_map),
        clue4(Grandchildren, Ages, Birthdays_map),
        clue5(Grandchildren, Ages, Birthdays_map),
    ]

    failed_clues = [idx for idx, ok in enumerate(clue_results) if not ok]
    return float(sum(clue_results)) / len(clue_results), failed_clues

import collections
import math

def verify(grid):
    # Define categories and their possible values
    BUSINESS_VALUES = {
        "$8 million": 8,
        "$12 million": 12,
        "$15 million": 15,
        "$25 million": 25,
        "$30 million": 30,
    }
    ENTREPRENEURS = ["Clara Chen", "Betty Baker", "James Lee", "Robert Ross", "Daniel Kim"]
    STATES = ["California", "Nevada", "Arizona", "Florida", "Texas"]

    # --- Data Structures for easier access ---
    # Using dictionaries to map each entity to its associated properties.
    # This allows direct lookup by name/value rather than iterating through rows.

    # Expected structure:
    # { "EntrepreneurName": {"value": int, "state": "StateName"}, ... }
    # { "StateName": {"value": int, "entrepreneur": "EntrepreneurName"}, ... }
    # { int_value: {"entrepreneur": "EntrepreneurName", "state": "StateName"}, ... }

    entrepreneurs_map = {}
    states_map = {}
    values_map = {}

    # Validate grid structure and populate maps
    if not isinstance(grid, list) or not grid:
        return (0.0, list(range(7))) # Total 7 clues

    # Use sets to check for uniqueness within categories
    seen_entrepreneurs = set()
    seen_states = set()
    seen_values = set()

    for r_idx, row in enumerate(grid):
        if not isinstance(row, list) or len(row) != 3:
            return (0.0, list(range(7)))

        value_str, entrepreneur_name, state_name = row

        # Validate and convert business value
        if value_str not in BUSINESS_VALUES:
            return (0.0, list(range(7)))
        value_int = BUSINESS_VALUES[value_str]

        # Validate entrepreneur name
        if entrepreneur_name not in ENTREPRENEURS:
            return (0.0, list(range(7)))

        # Validate state name
        if state_name not in STATES:
            return (0.0, list(range(7)))

        # Check for uniqueness
        if entrepreneur_name in seen_entrepreneurs or \
           state_name in seen_states or \
           value_int in seen_values:
            return (0.0, list(range(7))) # Duplicate entry found

        seen_entrepreneurs.add(entrepreneur_name)
        seen_states.add(state_name)
        seen_values.add(value_int)

        # Populate maps
        entrepreneurs_map[entrepreneur_name] = {
            "value": value_int,
            "state": state_name
        }
        states_map[state_name] = {
            "value": value_int,
            "entrepreneur": entrepreneur_name
        }
        values_map[value_int] = {
            "entrepreneur": entrepreneur_name,
            "state": state_name
        }

    # Ensure all categories are fully populated (e.g., 5 entrepreneurs, 5 states, 5 values)
    if len(entrepreneurs_map) != len(ENTREPRENEURS) or \
       len(states_map) != len(STATES) or \
       len(values_map) != len(BUSINESS_VALUES):
        return (0.0, list(range(7)))

    # --- Clue Definitions ---
    clue_results = [False] * 7 # Initialize with False for all 7 clues

    # 1. The entrepreneur from Texas had a business value somewhat less than Clara Chen.
    # "somewhat less" implies strictly less.
    if "Texas" in states_map and "Clara Chen" in entrepreneurs_map:
        texas_value = states_map["Texas"]["value"]
        clara_chen_value = entrepreneurs_map["Clara Chen"]["value"]
        clue_results[0] = texas_value < clara_chen_value

    # 2. Robert Ross's business was worth 8 million more than the entrepreneur from Florida.
    if "Robert Ross" in entrepreneurs_map and "Florida" in states_map:
        robert_ross_value = entrepreneurs_map["Robert Ross"]["value"]
        florida_value = states_map["Florida"]["value"]
        clue_results[1] = robert_ross_value == florida_value + 8

    # 3. The entrepreneur who owned a business valued at $25 million is from Arizona.
    if 25 in values_map and "Arizona" in states_map:
        clue_results[2] = values_map[25]["state"] == "Arizona"

    # 4. James Lee wasn't from California.
    if "James Lee" in entrepreneurs_map:
        clue_results[3] = entrepreneurs_map["James Lee"]["state"] != "California"

    # 5. James Lee's business was worth $12 million.
    if "James Lee" in entrepreneurs_map:
        clue_results[4] = entrepreneurs_map["James Lee"]["value"] == 12

    # 6. James Lee's business value was somewhat less than the entrepreneur from Florida.
    # "somewhat less" implies strictly less.
    if "James Lee" in entrepreneurs_map and "Florida" in states_map:
        james_lee_value = entrepreneurs_map["James Lee"]["value"]
        florida_value = states_map["Florida"]["value"]
        clue_results[5] = james_lee_value < florida_value

    # 7. The entrepreneur from Nevada was either the person with a business valued at $8 million or Betty Baker.
    if "Nevada" in states_map and 8 in values_map and "Betty Baker" in entrepreneurs_map:
        nevada_entrepreneur = states_map["Nevada"]["entrepreneur"]
        value_8_entrepreneur = values_map[8]["entrepreneur"]
        clue_results[6] = (nevada_entrepreneur == value_8_entrepreneur) or \
                          (nevada_entrepreneur == "Betty Baker")

    # --- Calculate Reward ---
    total_clues = len(clue_results)
    satisfied_clues = sum(1 for result in clue_results if result)
    failed_clues = [idx for idx, result in enumerate(clue_results) if not result]

    reward = float(satisfied_clues) / total_clues if total_clues > 0 else 0.0

    return (reward, failed_clues)

from dataclasses import dataclass

# Mappings for consistent ordering and easy lookup
PRICES = {
    "$7.99": 7.99,
    "$8.99": 8.99,
    "$9.99": 9.99,
    "$10.99": 10.99,
    "$11.99": 11.99,
}

@dataclass
class Runner:
    name: str
    price: float = None
    drink: str = None

@dataclass
class Drink:
    name: str
    price: float = None
    runner: str = None

# Clue functions
def clue0(Runners, Drinks):
    # 1. Alex ordered a latte.
    return Runners["Alex"].drink == "latte"

def clue1(Runners, Drinks):
    # 2. Alex paid 2 dollars more than Chris.
    return Runners["Alex"].price == Runners["Chris"].price + 2.0

def clue2(Runners, Drinks):
    # 3. Of the competitor who ordered a cappuccino and the competitor who ordered an espresso, one paid $9.99 and the other was Dana.
    cappuccino_runner = Drinks["cappuccino"].runner
    espresso_runner = Drinks["espresso"].runner

    # Check if one paid $9.99 and the other was Dana
    cond1 = (Drinks["cappuccino"].price == PRICES["$9.99"] and espresso_runner == "Dana")
    cond2 = (Drinks["espresso"].price == PRICES["$9.99"] and cappuccino_runner == "Dana")

    return cond1 or cond2

def clue3(Runners, Drinks):
    # 4. Dana paid 1 dollar more than Mark.
    return Runners["Dana"].price == Runners["Mark"].price + 1.0

def clue4(Runners, Drinks):
    # 5. The participant who ordered a mocha paid more than Chris.
    return Drinks["mocha"].price > Runners["Chris"].price

def clue5(Runners, Drinks):
    # 6. The contestant who paid $9.99 was either the competitor who ordered a cappuccino or the runner who ordered an espresso.
    runner_at_999 = None
    for runner_name, runner_obj in Runners.items():
        if runner_obj.price == PRICES["$9.99"]:
            runner_at_999 = runner_name
            break

    if runner_at_999 is None:
        return False # Should not happen with valid input, but defensive

    return (Runners[runner_at_999].drink == "cappuccino" or Runners[runner_at_999].drink == "espresso")

def verify(grid):
    runners_data = {}
    drinks_data = {}
    prices_in_grid = set()
    runners_in_grid = set()
    drinks_in_grid = set()

    # Expected entities for validation
    expected_prices = set(PRICES.keys())
    expected_runners = {"Alex", "Chris", "Dana", "Mark", "Sam"}
    expected_drinks = {"cappuccino", "espresso", "latte", "mocha", "tea"}

    # Parse grid into data structures
    try:
        for row in grid:
            if not (isinstance(row, list) and len(row) == 3):
                return (0.0, list(range(6))) # Malformed row

            price_str, runner_name, drink_name = row

            if price_str not in PRICES or runner_name not in expected_runners or drink_name not in expected_drinks:
                return (0.0, list(range(6))) # Unknown category item

            price_val = PRICES[price_str]

            # Check for duplicates within the grid rows
            if price_str in prices_in_grid or runner_name in runners_in_grid or drink_name in drinks_in_grid:
                return (0.0, list(range(6))) # Duplicate assignment

            prices_in_grid.add(price_str)
            runners_in_grid.add(runner_name)
            drinks_in_grid.add(drink_name)

            runners_data[runner_name] = Runner(name=runner_name, price=price_val, drink=drink_name)
            drinks_data[drink_name] = Drink(name=drink_name, price=price_val, runner=runner_name)

    except Exception:
        return (0.0, list(range(6))) # General parsing error

    # Validate that all expected entities are present and unique
    if not (prices_in_grid == expected_prices and runners_in_grid == expected_runners and drinks_in_grid == expected_drinks):
        return (0.0, list(range(6)))

    # Ensure all runners and drinks have been populated
    if len(runners_data) != len(expected_runners) or len(drinks_data) != len(expected_drinks):
        return (0.0, list(range(6)))

    # Execute clues
    clue_functions = [
        clue0,
        clue1,
        clue2,
        clue3,
        clue4,
        clue5,
    ]

    clue_results = []
    for i, clue_func in enumerate(clue_functions):
        try:
            clue_results.append(clue_func(runners_data, drinks_data))
        except KeyError:
            # This can happen if a clue references an entity that wasn't properly mapped,
            # which should be caught by the initial validation, but as a safeguard.
            return (0.0, list(range(len(clue_functions))))

    failed_clues = [idx for idx, ok in enumerate(clue_results) if not ok]

    total_clues = len(clue_results)
    satisfied_clues = sum(clue_results)

    reward = float(satisfied_clues) / total_clues if total_clues > 0 else 0.0

    return reward, failed_clues

