    fantasy_person = Genres["fantasy"]
    sci_fi_person = Genres["science fiction"]

    condition1 = (fantasy_person.price == PRICES["$27.99"] and sci_fi_person.book == "historical fiction")
    condition2 = (sci_fi_person.price == PRICES["$27.99"] and fantasy_person.book == "historical fiction")

    return condition1 or condition2

def clue5(Prices, Names, Genres, Books):
