    # Populate maps from grid
    try:
        for row in grid:
            if len(row) != 4: # Expecting 4 columns
                return 0.0, list(range(7))

            price_str, name_str, genre_str, book_str = row

            if price_str not in PRICES:
                return 0.0, list(range(7))
            price_val = PRICES[price_str]

            # Check for uniqueness within categories
            if price_val in Prices_map: return 0.0, list(range(7))
            if name_str in Names_map: return 0.0, list(range(7))
            if genre_str in Genres_map: return 0.0, list(range(7))
            if book_str in Books_map: return 0.0, list(range(7))

            Prices_map[price_val] = Price(value=price_val, name=name_str, genre=genre_str, book=book_str)
            Names_map[name_str] = Name(name=name_str, price=price_val, genre=genre_str, book=book_str)
